-- name: ListMembers :many
SELECT id, address_city, address_postcode, address_street, card_number, email, email_hash, full_name, joined_on, membership_ends_on, outstanding_fees, phones, status, tier, created_at, created_by_user_id, created_by_user_nameid, last_modified_at, last_modified_by_user_id, last_modified_by_user_nameid, is_deleted
FROM members
WHERE (sqlc.narg(tier)::VARCHAR(8) IS NULL OR tier = sqlc.narg(tier))
  AND (sqlc.narg(search)::text IS NULL
       OR position(lower(sqlc.narg(search)) in lower(card_number)) > 0
       OR position(lower(sqlc.narg(search)) in lower(full_name)) > 0)
  AND is_deleted = false
ORDER BY CASE WHEN sqlc.arg(sort)::text = 'fullName' THEN full_name END ASC,
    CASE WHEN sqlc.arg(sort)::text = '-fullName' THEN full_name END DESC,
    CASE WHEN sqlc.arg(sort)::text = 'joinedOn' THEN joined_on END ASC,
    CASE WHEN sqlc.arg(sort)::text = '-joinedOn' THEN joined_on END DESC,
    id
LIMIT sqlc.arg(page_size) OFFSET sqlc.arg(page_offset);

-- name: ListMembersTotal :one
SELECT count(*) AS total
FROM members
WHERE (sqlc.narg(tier)::VARCHAR(8) IS NULL OR tier = sqlc.narg(tier))
  AND (sqlc.narg(search)::text IS NULL
       OR position(lower(sqlc.narg(search)) in lower(card_number)) > 0
       OR position(lower(sqlc.narg(search)) in lower(full_name)) > 0)
  AND is_deleted = false;
